'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
import {readFinancialPostingReview,readFinancialCommit,type FinancialAccounts,type FinancialPostingSelection} from '@/lib/financial-migration-posting';
import type {HandoffScope} from '@/lib/cashier-handoff';
type Props={scope:HandoffScope;batch:string;onCompleted:()=>void;onRecoveryLock?:(locked:boolean)=>void};
type Pending={id:string;selection:FinancialPostingSelection;review:Record<string,unknown>};
export function FinancialMigrationPosting(props:Props){return <PostingWorkspace key={[props.scope.tenant,props.scope.property,props.scope.actor,props.batch].join(':')} {...props}/>}
function PostingWorkspace({scope,batch,onCompleted,onRecoveryLock}:Props){
 const [setup,setSetup]=useState<AccountingSetup|null>(null),[accounts,setAccounts]=useState<FinancialAccounts>({receivable:'',prepayment:'',security:'',offset:''}),[period,setPeriod]=useState(''),[review,setReview]=useState<ReturnType<typeof readFinancialPostingReview>|null>(null),[pending,setPending]=useState<Pending|null>(null),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 const alive=useRef(false),lock=useRef(false),key=['irp.financial.commit.v1',scope.tenant,scope.property,scope.actor,batch].join(':');
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const saved=JSON.parse(raw) as Pending;if(typeof saved.id!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(saved.id)||saved.selection.scope.tenant!==scope.tenant||saved.selection.scope.property!==scope.property||saved.selection.scope.actor!==scope.actor||saved.selection.batch!==batch)throw Error('Saved posting belongs to another workspace.');setReview(readFinancialPostingReview(saved.review,saved.selection));setPending(saved);setAccounts(saved.selection.accounts);setPeriod(saved.selection.period)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to restore posting.')}return()=>{alive.current=false}},[key]);
 useEffect(()=>{onRecoveryLock?.(!ready||busy||!!pending)},[ready,busy,pending,onRecoveryLock]);
 async function identify(){const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen migration.');}
 function changed(){setReview(null);setConfirmed(false);setMessage('')}
 async function run(kind:'setup'|'preview'|'commit'|'check'|'cancel'){
  if(lock.current||!ready)return;lock.current=true;setBusy(true);setError('');setMessage('');
  try{await identify();const args={p_tenant:scope.tenant,p_property:scope.property};
   if(kind==='setup'){if(pending)throw Error('Resolve the saved posting first.');const value=readAccountingSetup(await hotelRpc('gl_setup',args),scope.tenant,scope.property);await identify();if(alive.current){setSetup(value);changed()}return}
   if(kind==='preview'){if(pending)throw Error('Resolve the saved posting first.');const selection={scope,batch,period,accounts};const value=readFinancialPostingReview(await hotelRpc('preview_financial_migration_posting',{...args,p_batch:batch,p_period:period,p_accounts:accounts}),selection);await identify();if(alive.current){setReview(value);setConfirmed(false)}return}
   let request=pending;
   if(!request){if(kind!=='commit'||!confirmed||!review)throw Error('Review and confirm the opening balances.');request={id:crypto.randomUUID(),selection:{scope,batch,period,accounts},review:review.raw};readFinancialPostingReview(request.review,request.selection);if(sessionStorage.getItem(key))throw Error('Recover the existing posting first.');sessionStorage.setItem(key,JSON.stringify(request));setPending(request)}
   let complete=false,cancelled=false;
   if(kind==='commit'){if(!confirmed)throw Error('Confirm this posting.');readFinancialCommit(await hotelRpc('commit_financial_migration',{...args,p_request:request.id,p_review:request.review,p_confirmed:true}),request);complete=true}
   else{
    if(kind==='cancel'){if(!cancelConfirmed)throw Error('Confirm cancellation.');await hotelRpc('cancel_financial_migration_commit',{...args,p_request:request.id,p_batch:batch,p_confirmed:true})}
    const status=await hotelRpc<Record<string,unknown>>('financial_migration_commit_status',{...args,p_request:request.id});
    if(status.schema_version!==1||status.tenant_id!==scope.tenant||status.property_id!==scope.property||status.actor_id!==scope.actor||status.request_id!==request.id||typeof status.found!=='boolean'||typeof status.cancelled!=='boolean'||status.found&&status.cancelled||!status.found&&status.result!==null)throw Error('Posting status does not match this request.');
    if(status.found){readFinancialCommit(status.result,request);complete=true}cancelled=status.cancelled;
   }
   await identify();if(alive.current){if(complete||cancelled){sessionStorage.removeItem(key);setPending(null);setConfirmed(false);setCancelConfirmed(false);setReview(null);setMessage(complete?'Opening balances posted.':'Posting request cancelled. Review again before posting.');if(complete)onCompleted()}else setMessage('No posting found. Retry or cancel the saved request.')}
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to complete migration posting.')}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 return <section className="card pilot-settings"><h2>Review opening balance posting</h2><button type="button" disabled={busy||!ready||!!pending} onClick={()=>void run('setup')}>Load opening accounts and periods</button><fieldset disabled={busy||!ready||!!pending}>{(['receivable','prepayment','security','offset'] as const).map(category=><label className="field" key={category}>{category==='offset'?'Opening balance offset account':`${category[0].toUpperCase()+category.slice(1)} account`}<select value={accounts[category]} onChange={e=>{setAccounts({...accounts,[category]:e.target.value});changed()}}><option value="">Choose account</option>{setup?.accounts.filter(a=>a.active&&a.kind===(category==='receivable'?'asset':category==='offset'?'equity':'liability')).map(a=><option key={a.account_id} value={a.account_id}>{a.code} {a.name}</option>)}</select></label>)}<label className="field">Opening accounting period<select value={period} onChange={e=>{setPeriod(e.target.value);changed()}}><option value="">Choose period</option>{setup?.periods.filter(p=>!p.closed).map(p=><option key={p.period_id} value={p.period_id}>{p.start_date} to {p.end_date_exclusive} (end excluded)</option>)}</select></label></fieldset><button type="button" disabled={busy||!ready||!!pending||!period||Object.values(accounts).some(v=>!v)} onClick={()=>void run('preview')}>Preview opening posting</button>{review&&<section aria-label="Opening posting review"><p>Cutover date: {review.cutover}</p>{(['receivable','prepayment','security'] as const).map(category=><p key={category}>{category}: {bankCloseMoney(review.totals[category].toString())}</p>)}<p>{review.rows.length} opening items. This records migrated balances; it does not collect money.</p><div className="table-wrap"><table><caption>Source opening balances</caption><thead><tr><th>Source item</th><th>Reference</th><th>Category</th><th>Amount (USD)</th></tr></thead><tbody>{review.rows.map(row=><tr key={row.id}><td>{row.source}</td><td>{row.reference}</td><td>{row.category}</td><td>{bankCloseMoney(row.amount)}</td></tr>)}</tbody></table></div><p>Existing destination folio balances are shown separately. They may include the same quoted charges as a source receivable and must be reconciled before cutover.</p><ul>{Array.from(new Map(review.rows.map(row=>[row.reservation,row])).values()).map(row=><li key={row.reservation}>Reservation {row.reservation}: {row.destinationBalance===null?'Charges unavailable':bankCloseMoney(row.destinationBalance)}</li>)}</ul><label><input type="checkbox" disabled={busy} checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I reviewed the source totals and opening accounts</label><button type="button" disabled={busy||!confirmed} onClick={()=>void run('commit')}>{pending?'Retry opening posting':'Post opening balances'}</button></section>}{pending&&<><button type="button" disabled={busy} onClick={()=>void run('check')}>Check opening posting outcome</button><label><input type="checkbox" disabled={busy} checked={cancelConfirmed} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel if not posted</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel opening posting request</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
